return ['x-generator'=>'GlotPress/4.0.1','translation-revision-date'=>'2023-12-17 01:16:51+0000','plural-forms'=>'nplurals=1; plural=0;','project-id-version'=>'Plugins - Edit Author Slug - Stable (latest release)','language'=>'zh_TW','messages'=>['Your iThemes settings suggest you don\'t want the %1$s being used as an author slug. Leaving it set to %2$s will still work, but you may wish to change to something different.'=>'這個網站的 iThemes 設定表示網站管理員不想使用 %1$s 做為作者代稱。將設定保留為 %2$s 仍能正確執行，但或許網站管理員會想要變更為不同的設定。','Demo:'=>'預覽結果:','This also applies to other users.'=>'這項操作會套用至其他使用者。','You can customize your own author slug by visiting your profile page. '=>'網站管理員可以在 [個人資料] 頁面自訂個人專屬作者代稱。','Settings menu itemEdit Author Slug'=>'編輯作者代稱','Plugin settings page headingEdit Author Slug'=>'編輯作者代稱','hash'=>'雜湊值','userid'=>'使用者 ID','<strong>ERROR</strong>: Your iThemes settings prevent your author slug from being the same as your username.'=>'<strong>錯誤:</strong> 這個網站的 iThemes 設定防止作者代稱與使用者名稱使用相同名稱。','Use class constant, BA_Edit_Author_Slug::DB_VERSION, instead.'=>'改用類別常數 BA_Edit_Author_Slug::DB_VERSION。','Use class constant, BA_Edit_Author_Slug::VERSION, instead.'=>'改用類別常數 BA_Edit_Author_Slug::VERSION。','Use the %1$s rewrite tag to customize the role-based author base. If you set the author base to "%2$s", the resulting author structure will be something like "%3$s".'=>'使用 %1$s 重新寫入標籤以自訂以使用者角色為上層目錄的作者目錄起點。當網站管理員將 [作者目錄起點] 設定為 %2$s，作者代稱結構的結果便會是 %3$s。','Set user\'s Author Base according to their role.'=>'將作者目錄起點的上層目錄設定為使用者角色代稱','Remove the "front" portion of the author permalink structure.'=>'移除作者永久連結結構的前段部分','Remove Front'=>'移除前段部分','https://github.com/thebrandonallen/'=>'https://github.com/thebrandonallen/','Brandon Allen'=>'Brandon Allen','Allows an Admin (or capable user) to edit the author slug of a user, and change the Author Base. <em>i.e. - (WordPress default structure) http://example.com/author/username/ (Plugin allows) http://example.com/ninja/master-ninja/</em>'=>'允許網站管理員 (或其他具備相關權限的使用者) 編輯使用者的作者代稱及變更作者目錄起點。舉例來說，<strong>將 WordPress 預設結構 http://example.com/author/username/ 透過外掛變更為 http://example.com/ninja/master-ninja/</strong>。','https://github.com/thebrandonallen/edit-author-slug/'=>'https://github.com/thebrandonallen/edit-author-slug/','%d user author slug updated.'=>'%d 個使用者的作者代稱已更新。','Settings'=>'設定','Default bulk update author slug options'=>'批次更新作者代稱預設選項','Update all users according to the below Author Slug setting. This will only be run after clicking "Save Changes".'=>'啟用這項設定並點擊 [儲存設定] 後，便會依據下方的作者代稱設定更新全部使用者的作者代稱','Update all users at once based on the specified Author Slug structure.'=>'依據指定的作者代稱結構更新全部使用者的作者代稱。','Default author slug options'=>'作者代稱預設選項','lastname-firstname'=>'姓氏-名字','firstname-lastname'=>'名字-姓氏','lastname'=>'姓氏','firstname'=>'名字','displayname'=>'顯示名稱','nickname'=>'暱稱','username (Default)'=>'使用者名稱 (預設)','Automatically update Author Slug when a user updates their profile.'=>'使用者更新個人資料後，自動更新對應的作者代稱','Defaults to \'author\''=>'預設值為 author。','This could have SEO repercussions if users update their profiles frequently, and it will override any manual editing of the Author Slug you may have previously completed.'=>'如果使用者經常更新個人資料，便會對 SEO 產生不良影響，並且會覆寫網站管理員之前對作者代稱進行的任何手動編輯。','Allow Author Slugs to be automatically updated, and set the default Author Slug structure for users. Automatic updating will only occur when a user can\'t edit Author Slugs on their own.'=>'允許自動更新作者代稱，並為使用者設定預設作者代稱結構。僅有使用者無法編輯個人專屬作者代稱時，才會自動更新。','Change your author base to something more fun!'=>'變更網站的作者目錄起點，能讓網站變的更有趣！','Bulk Update'=>'批次更新','Bulk Update Author Slugs'=>'批次更新作者代稱','Author Slug Structure'=>'作者代稱結構','Automatically Update'=>'自動更新','Automatic Author Slug Creation'=>'自動建立作者代稱','Role Slugs'=>'使用者角色代稱','Role-Based Author Base'=>'以使用者角色為上層目錄的作者目錄起點','Author Base'=>'作者目錄起點','Edit Author Slug Settings'=>'Edit Author Slug 設定','<strong>ERROR</strong>: The author slug, %1$s, already exists. Please try something different.'=>'<strong>錯誤:</strong> 作者代稱 %1$s 已存在。請使用不同的作者代稱。','<strong>ERROR</strong>: An author slug may not be longer than 50 characters.'=>'<strong>錯誤:</strong> 作者代稱不能超過 50 個字元。','<strong>ERROR</strong>: That author slug appears to be invalid. Please try something different.'=>'<strong>錯誤:</strong> 無效的作者代稱。請使用不同的作者代稱。','<strong>ERROR</strong>: An author slug can only contain alphanumeric characters, underscores (_) and dashes (-).'=>'<strong>錯誤:</strong> 作者代稱僅能使用數字、英文字母、底線 (_) 及連字號 (-)。','<strong>ERROR</strong>: An author slug cannot be blank. Please try again.'=>'<strong>錯誤:</strong> 作者代稱不能留空。請再試一次。','Custom author slug:'=>'自訂作者代稱:','Enter a custom author slug in the following field'=>'在下方欄位輸入自訂作者代稱','Custom:'=>'自訂:','Author Slug'=>'作者代稱','ie. - \'user-name\', \'firstname-lastname\', or \'master-ninja\''=>'例如 user-name、firstname-lastname 或 master-ninja。','Choose an Author Slug based on the above profile information, or create your own.'=>'請選取根據上方個人資料設定所得的作者代稱，或自訂專屬作者代稱。','Edit Author Slug'=>'Edit Author Slug']];